import copy
import json
from pathlib import Path
import unittest

from verifier import classify


class ClassifyTests(unittest.TestCase):
    def setUp(self):
        self.reports = json.loads(Path(__file__).with_name('reports.json').read_text())
        self.report = copy.deepcopy(self.reports[0])

    def test_recorded_reports(self):
        self.assertEqual(
            [classify(report) for report in self.reports],
            ['killed', 'invalid', 'invalid', 'survived', 'invalid'],
        )

    def test_each_failure_identity_field_must_match(self):
        for field, value in (
            ('selected_test', 'test_other'),
            ('stage', 'setup'),
            ('actual_error', 'TypeError'),
            ('assertion_id', 'other_assertion'),
        ):
            with self.subTest(field=field):
                report = dict(self.report, **{field: value})
                self.assertEqual(classify(report), 'invalid')

    def test_any_nonzero_code_can_prove_targeted_exception(self):
        self.report['actual_error'] = 'TypeError'
        self.report['target']['error'] = 'TypeError'
        self.report['traceback_source'] = "raise AssertionError('displayed only')"
        for code in (1, 2, -9):
            with self.subTest(code=code):
                self.report['returncode'] = code
                self.assertEqual(classify(self.report), 'killed')

    def test_traceback_source_does_not_determine_classification(self):
        for source in ('', 'raise TypeError()', 'raise AssertionError()'):
            with self.subTest(source=source):
                self.report['traceback_source'] = source
                self.assertEqual(classify(self.report), 'killed')

    def test_success_receipt_and_selection(self):
        # Absence retains legacy behavior; explicit empty receipts take precedence.
        for selected in ('test_limit', 'test_other'):
            for receipt in ('absent', None, 0, 1, 3):
                with self.subTest(selected=selected, receipt=receipt):
                    report = dict(self.report, returncode=0, selected_test=selected)
                    if receipt != 'absent':
                        report['tests_executed'] = receipt
                    if receipt in (None, 0):
                        expected = 'unrun'
                    elif selected == 'test_limit':
                        expected = 'survived'
                    else:
                        expected = 'invalid'
                    self.assertEqual(classify(report), expected)

    def test_empty_receipt_does_not_override_nonzero_contract(self):
        for receipt in (None, 0):
            with self.subTest(receipt=receipt):
                self.report['tests_executed'] = receipt
                self.assertEqual(classify(self.report), 'killed')


if __name__ == '__main__':
    unittest.main()

